349		}
350		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
351			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
352			return
353		}
354	
355		if req.DeviceID == "" {
356			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
357			return
358		}
359		// baseCursor must be present and a non-negative integer (no fractions,
360		// strings, booleans or null).
361		if len(req.BaseCursor) == 0 {
362			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
363			return
364		}
365		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
366		if !ok {
367			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
368			return
369		}
370		if req.Change == nil {
371			writeError(w, http.StatusBadRequest, "change must be an object")
372			return
373		}
374		if req.Change.ID == "" {
375			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
376			return
377		}
378		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
379			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
380			return
381		}
382	
383		result, err := s.MergeChange(documentID, baseCursor, store.Change{
384			ID:       req.Change.ID,
385			DeviceID: req.DeviceID,
386			Payload:  req.Change.Payload,
387		})
388		if err != nil {
389			var conflict *store.ErrConflict
390			switch {
391			case errors.Is(err, store.ErrStaleCursor):
392				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
393				return
394			case errors.As(err, &conflict):
395				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
396				return
397			default:
398				writeError(w, http.StatusInternalServerError, "failed to merge change")
399				return
400			}
401		}
402	
403		writeJSON(w, http.StatusOK, result)
404	}
405	
406	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
407		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
408	
409		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
410		if err != nil || mediaType != "application/json" {
411			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
412			return
413		}
414	
415		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
416		var req snapshotPostRequest
417		dec := json.NewDecoder(r.Body)
418		if err := dec.Decode(&req); err != nil {
419			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
420			return
421		}
422		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
423			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
424			return
425		}
426	
427		cursor, ok := parseNonNegativeInt(req.Cursor)
428		if !ok {
429			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
430			return
431		}
432		if len(req.State) == 0 {
433			writeError(w, http.StatusBadRequest, "state is required")
434			return
435		}
436	
437		created, err := s.PutSnapshot(documentID, cursor, req.State)
438		if err != nil {
439			var conflict *store.ErrSnapshotConflict
440			switch {
441			case errors.Is(err, store.ErrSnapshotBase):
442				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
443				return
444			case errors.As(err, &conflict):
445				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
446				return
447			default:
448				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
449				return
450			}
451		}
452	
453		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
454	}
455	
456	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
457		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
458	
459		cursor, ok := parseCursorPath(r.PathValue("cursor"))
460		if !ok {
461			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
462			return
463		}
464	
465		state, err := s.GetSnapshot(documentID, cursor)
466		if err != nil {
467			if errors.Is(err, store.ErrSnapshotNotFound) {
468				writeError(w, http.StatusNotFound, "snapshot not found")
469				return
470			}
471			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
472			return
473		}
474	
475		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
476	}
477	
478	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
479		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
480	
481		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
482		if err != nil || mediaType != "application/json" {
483			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
484			return
485		}
486	
487		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
488		var req restoreRequest
489		dec := json.NewDecoder(r.Body)
490		if err := dec.Decode(&req); err != nil {
491			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
492			return
493		}
494		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
495			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
496			return
497		}
498	
499		if req.DeviceID == "" {
500			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
501			return
502		}
503		if req.ChangeID == "" {
504			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
505			return
506		}
507		// snapshotCursor must be present and a positive integer (no fractions,
508		// strings, booleans, null or zero).
509		if len(req.SnapshotCursor) == 0 {
510			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
511			return
512		}
513		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
514		if !ok {
515			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
516			return
517		}
518	
519		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
520		if err != nil {
521			var conflict *store.ErrRestoreConflict
522			switch {
523			case errors.Is(err, store.ErrSnapshotNotFound):
524				writeError(w, http.StatusNotFound, "snapshot not found")
525				return
526			case errors.As(err, &conflict):
527				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
528				return
529			default:
530				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
531				return
532			}
533		}
534	
535		writeJSON(w, http.StatusOK, result)
536	}
537	
538	// handleSetPermission grants or revokes a registered device's access to one
539	// document. Devices start authorized, so the first revoke is the first write;
540	// repeating the current state is idempotent (changed=false). A rejected
541	// request (bad content type, malformed JSON, trailing content, empty or
542	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
543	// unregistered device is a 404 JSON error.
544	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
545		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
546	
547		var req permissionRequest
548		if !decodeJSONBody(w, r, &req) {
549			return
550		}
551		if req.DeviceID == "" {
552			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
553			return
554		}
555		var authorized bool
556		switch req.Action {
557		case "grant":
558			authorized = true
559		case "revoke":
560			authorized = false
561		default:
562			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
563			return
564		}
565	
566		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
567		if err != nil {
568			if errors.Is(err, store.ErrDeviceNotFound) {
569				writeError(w, http.StatusNotFound, "device not found")
570				return
571			}
572			writeError(w, http.StatusInternalServerError, "failed to update permission")
573			return
574		}
575	
576		writeJSON(w, http.StatusOK, map[string]any{
577			"deviceId":   req.DeviceID,
578			"authorized": authorized,
579			"changed":    changed,
580		})
581	}
582	
583	// parseCursorPath reports whether raw is a decimal non-negative integer and
584	// returns its value. Signs, fractions and other adornments are rejected.
585	func parseCursorPath(raw string) (int64, bool) {
586		if raw == "" {
587			return 0, false
588		}
589		for _, c := range raw {
590			if c < '0' || c > '9' {
591				return 0, false
592			}
593		}
594		n, err := strconv.ParseInt(raw, 10, 64)
595		if err != nil {
596			return 0, false
597		}
598		return n, true
599	}
600	
601	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
602	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
603		var n int64
604		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
605			return 0, false
606		}
607		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
608		// require the literal to contain no fraction or exponent.
609		trimmed := strings.TrimSpace(string(raw))
610		if trimmed == "" || trimmed[0] == '-' {
611			return 0, false
612		}
613		for _, c := range trimmed {
614			if c < '0' || c > '9' {
615				return 0, false
616			}
617		}
618		return n, true
619	}
620	
621	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
622	// strings, booleans, null and negative numbers are rejected.
623	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
624		n, ok := parseNonNegativeInt(raw)
625		if !ok || n < 1 {
626			return 0, false
627		}
628		return n, true
629	}
630	
631	// isJSONObject reports whether raw decodes to a JSON object (not null, an
632	// array or a scalar).
633	func isJSONObject(raw json.RawMessage) bool {
634		var m map[string]json.RawMessage
635		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
636			return false
637		}
638		return true
639	}
640	
641	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
642		documentID := r.PathValue("documentID")
643	
644		after, limit, ok := parseChangesQuery(w, r)
645		if !ok {
646			return
647		}
648	
649		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
650		if err != nil {
651			writeError(w, http.StatusInternalServerError, "failed to list changes")
652			return
653		}
654	
655		writeChangesPage(w, changes, nextCursor)
656	}
657	
658	// handleSessionChanges is the session-scoped view of the existing change log:
659	// both path identifiers must be non-empty (the empty-segment guard rejects
660	// those before routing) and the session must currently exist, after which the
661	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
662	// the session's device has been revoked permission for the document, which is
663	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
664	// read; the change log itself is untouched.
665	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
666		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
667		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
668	
669		// Malformed query parameters are a request-shape error (400) checked
670		// before the resource lookup (404), matching the snapshot GET ordering.
671		after, limit, ok := parseChangesQuery(w, r)
672		if !ok {
673			return
674		}
675	
676		deviceID, err := s.SessionDevice(sessionID)
677		if err != nil {
678			if errors.Is(err, store.ErrSessionNotFound) {
679				writeError(w, http.StatusNotFound, "session not found")
680				return
681			}
682			writeError(w, http.StatusInternalServerError, "failed to look up session")
683			return
684		}
685	
686		authorized, err := s.DocumentAuthorized(documentID, deviceID)
687		if err != nil {
688			writeError(w, http.StatusInternalServerError, "failed to look up permission")
689			return
690		}
691		if !authorized {
692			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
693			return
694		}
695	
696		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
697		if err != nil {
698			writeError(w, http.StatusInternalServerError, "failed to list changes")
699			return
700		}
701	
702		writeChangesPage(w, changes, nextCursor)
703	}
704	
705	// parseChangesQuery parses the shared after/limit pagination parameters,
706	// writing the documented 400 on an illegal value. It is shared by the
707	// document-scoped and session-scoped change listings so their query semantics
708	// cannot drift apart.
709	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
710		q := r.URL.Query()
711	
712		after = 0
713		if raw := q.Get("after"); raw != "" {
714			v, err := strconv.ParseInt(raw, 10, 64)
715			if err != nil || v < 0 {
716				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
717				return 0, 0, false
718			}
719			after = v
720		}
721	
722		limit = defaultListLimit
723		if raw := q.Get("limit"); raw != "" {
724			v, err := strconv.ParseInt(raw, 10, 64)
725			if err != nil || v < 1 || v > maxListLimit {
726				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
727				return 0, 0, false
728			}
729			limit = v
730		}
731	
732		return after, limit, true
733	}
734	
735	// writeChangesPage renders a change listing page in the shared response shape.
736	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
737		writeJSON(w, http.StatusOK, map[string]any{
738			"changes":    changes,
739			"nextCursor": nextCursor,
740		})
741	}
742	
743	func writeJSON(w http.ResponseWriter, status int, v any) {
744		w.Header().Set("Content-Type", "application/json")
745		w.WriteHeader(status)
746		_ = json.NewEncoder(w).Encode(v)
747	}
748	
749	func writeError(w http.ResponseWriter, status int, message string) {
750		writeJSON(w, status, map[string]string{"error": message})
751	}
